import dspy
from litellm.utils import Choices, Message, ModelResponse

class CorpLM(dspy.BaseLM):
    def __init__(self):
        super().__init__(model="corp/mock", model_type="chat", temperature=0.0, max_tokens=1000, cache=True)

    @property
    def supports_response_schema(self):
        return True

    @property
    def supported_params(self):
        return {"response_format"}

    def forward(self, prompt=None, messages=None, **kwargs):
        if "response_format" in kwargs:
            content = '{"answer": "json path"}'
        else:
            content = "[[ ## answer ## ]]\nchat path\n\n[[ ## completed ## ]]"
        return ModelResponse(choices=[Choices(message=Message(role="assistant", content=content))], model="corp/mock")

    async def aforward(self, prompt=None, messages=None, **kwargs):
        return self.forward(prompt=prompt, messages=messages, **kwargs)

lm = CorpLM()
with dspy.context(lm=lm, adapter=dspy.ChatAdapter()):
    chat_result = dspy.Predict("question -> answer")(question="hello")

class JsonSig(dspy.Signature):
    question: str = dspy.InputField()
    answer: str = dspy.OutputField()

with dspy.context(lm=lm, adapter=dspy.JSONAdapter()):
    json_result = dspy.Predict(JsonSig)(question="hello")

print(chat_result.answer)
print(json_result.answer)
assert chat_result.answer == "chat path"
assert json_result.answer == "json path"
