    return None

dspy.configure(lm=dummy_lm)
try:
    dspy.Predict("question -> answer")(question="Why did a chicken cross the kitchen?")
except ValueError as e:
    errors["callable"] = str(e)

print(errors)
assert "No LM is loaded" in errors["none"]
assert "LM must be an instance of `dspy.BaseLM`, not a string." in errors["string"]
assert "LM must be an instance of `dspy.BaseLM`, not <class 'function'>." in errors["callable"]
